ALTER TABLE business_inquiries ADD COLUMN legacy_status VARCHAR(64), MODIFY created_at DATETIME(6) NOT NULL, MODIFY consent_at DATETIME(6) NOT NULL, MODIFY updated_at DATETIME(6) NOT NULL;
CREATE TABLE legacy_imports (source_sha256 CHAR(64) PRIMARY KEY, bundle_sha256 CHAR(64) NOT NULL, workspace_id CHAR(36) NOT NULL, table_count INT UNSIGNED NOT NULL, row_count INT UNSIGNED NOT NULL, imported_at DATETIME(6) NOT NULL, FOREIGN KEY(workspace_id) REFERENCES workspaces(id)) ENGINE=InnoDB;
CREATE TABLE legacy_tables (source_sha256 CHAR(64) NOT NULL, table_name VARCHAR(160) NOT NULL, column_names JSON NOT NULL, row_count INT UNSIGNED NOT NULL, copy_sha256 CHAR(64) NOT NULL, copy_payload MEDIUMBLOB NOT NULL, PRIMARY KEY(source_sha256,table_name), FOREIGN KEY(source_sha256) REFERENCES legacy_imports(source_sha256)) ENGINE=InnoDB;
CREATE TABLE legacy_rows (source_sha256 CHAR(64) NOT NULL, table_name VARCHAR(160) NOT NULL, row_index INT UNSIGNED NOT NULL, payload JSON NOT NULL, payload_sha256 CHAR(64) NOT NULL, PRIMARY KEY(source_sha256,table_name,row_index), FOREIGN KEY(source_sha256,table_name) REFERENCES legacy_tables(source_sha256,table_name)) ENGINE=InnoDB;
